const normalize=(value:string)=>value.normalize('NFKC').toLocaleLowerCase('ru-RU').replace(/ё/g,'е').replace(/\s+/g,' ').trim();
const byTopic=new Map(sceneStoryboards.map(story=>[normalize(story.family)+'|'+normalize(story.topic),story]));
export function sceneStoryboard(recipe:Pick<SceneRecipe,'family'|'topic'>):SceneStoryboard|null {return byTopic.get(normalize(recipe.family)+'|'+normalize(recipe.topic))??null;}
